create extension if not exists pgcrypto;

create type public.moment_status as enum ('pending_upload','waiting_for_friend','reply_uploading','completed','expired','cancelled','failed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text not null check (username ~ '^[a-z0-9_]{3,24}$'), display_name text not null check (char_length(display_name) between 1 and 50), avatar_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index profiles_username_unique on public.profiles(lower(username));
create table public.friend_requests (id uuid primary key default gen_random_uuid(), sender_id uuid not null references public.profiles(id) on delete cascade, recipient_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check (status in ('pending','accepted','rejected','cancelled')), created_at timestamptz not null default now(), responded_at timestamptz, check (sender_id <> recipient_id));
create unique index friend_requests_one_pending on public.friend_requests(sender_id, recipient_id) where status = 'pending';
create table public.friendships (user_low uuid not null references public.profiles(id) on delete cascade, user_high uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key (user_low,user_high), check (user_low < user_high));
create table public.blocks (blocker_id uuid not null references public.profiles(id) on delete cascade, blocked_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key (blocker_id,blocked_id), check (blocker_id <> blocked_id));
create table public.moments (id uuid primary key default gen_random_uuid(), initiator_id uuid not null references public.profiles(id) on delete cascade, responder_id uuid not null references public.profiles(id) on delete cascade, status public.moment_status not null default 'pending_upload', idempotency_key uuid not null, expires_at timestamptz not null default now() + interval '48 hours', completed_at timestamptz, created_at timestamptz not null default now(), unique (initiator_id,idempotency_key), check (initiator_id <> responder_id));
create index moments_participant_feed on public.moments(initiator_id,created_at desc); create index moments_responder_feed on public.moments(responder_id,created_at desc);
create table public.photos (id uuid primary key default gen_random_uuid(), moment_id uuid not null references public.moments(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, side smallint not null check (side in (1,2)), storage_path text not null, width int not null check (width > 0), height int not null check (height > 0), created_at timestamptz not null default now(), unique(moment_id,side), unique(storage_path));
create table public.reactions (moment_id uuid not null references public.moments(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, emoji text not null check (char_length(emoji) between 1 and 16), created_at timestamptz not null default now(), primary key(moment_id,user_id));

alter table public.profiles enable row level security; alter table public.friend_requests enable row level security; alter table public.friendships enable row level security; alter table public.blocks enable row level security; alter table public.moments enable row level security; alter table public.photos enable row level security; alter table public.reactions enable row level security;
create policy "profiles self read" on public.profiles for select to authenticated using (id = auth.uid()); create policy "profiles self update" on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy "friend requests participants read" on public.friend_requests for select to authenticated using (auth.uid() in (sender_id,recipient_id)); create policy "friend request sender create" on public.friend_requests for insert to authenticated with check (sender_id = auth.uid());
create policy "friendships participants read" on public.friendships for select to authenticated using (auth.uid() in (user_low,user_high)); create policy "blocks owner all" on public.blocks for all to authenticated using (blocker_id = auth.uid()) with check (blocker_id = auth.uid());
create policy "moments participants read" on public.moments for select to authenticated using (auth.uid() in (initiator_id,responder_id)); create policy "moments initiator create" on public.moments for insert to authenticated with check (initiator_id = auth.uid());
create policy "photos participants read" on public.photos for select to authenticated using (exists(select 1 from public.moments m where m.id = moment_id and auth.uid() in (m.initiator_id,m.responder_id))); create policy "photos owner create" on public.photos for insert to authenticated with check (owner_id = auth.uid() and exists(select 1 from public.moments m where m.id = moment_id and auth.uid() in (m.initiator_id,m.responder_id)));
create policy "reactions participants" on public.reactions for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid() and exists(select 1 from public.moments m where m.id = moment_id and auth.uid() in (m.initiator_id,m.responder_id)));

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('jello-photos','jello-photos',false,12582912,array['image/jpeg','image/heic','image/png']) on conflict(id) do nothing;
create policy "photo object participant read" on storage.objects for select to authenticated using (bucket_id='jello-photos' and exists(select 1 from public.photos p join public.moments m on m.id=p.moment_id where p.storage_path=name and auth.uid() in (m.initiator_id,m.responder_id)));
create policy "photo object owner insert" on storage.objects for insert to authenticated with check (bucket_id='jello-photos' and (storage.foldername(name))[1]=auth.uid()::text);
